const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define area of interest - Rasheed (Rosetta), Egypt
  const point = ee.Geometry.Point([30.4, 31.4]);
  const aoi = point.buffer(5000); // 5km radius to capture shoreline

  // 2. Load and process 1984 image (Landsat 5)
  const date1984 = ee.Date('1984-07-25');
  const col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(date1984.advance(-15, 'day'), date1984.advance(15, 'day'))
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1984 = col1984.size().getInfo();
  console.log(`1984 Images found: ${size1984}`);

  if (size1984 === 0) {
    console.log('No Landsat 5 data for 1984 period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Load and process 2021 image (Landsat 8)
  const date2021 = ee.Date('2021-08-16');
  const col2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(aoi)
    .filterDate(date2021.advance(-15, 'day'), date2021.advance(15, 'day'))
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size2021 = col2021.size().getInfo();
  console.log(`2021 Images found: ${size2021}`);

  if (size2021 === 0) {
    console.log('No Landsat 8 data for 2021 period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Process 1984 image - calculate MNDWI
  const img1984 = col1984.median();
  const mndwi1984 = img1984.normalizedDifference(['SR_B2', 'SR_B5']).rename('mndwi');
  const water1984 = mndwi1984.gt(0);

  // 5. Process 2021 image - calculate MNDWI
  const img2021 = col2021.median();
  const mndwi2021 = img2021.normalizedDifference(['SR_B3', 'SR_B6']).rename('mndwi');
  const water2021 = mndwi2021.gt(0);

  // 6. Calculate water area for both periods
  const waterArea1984 = water1984.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  }).get('mndwi');

  const waterArea2021 = water2021.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  }).get('mndwi');

  const pixelCount1984 = water1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  }).get('mndwi');

  const area1984 = waterArea1984.getInfo();
  const area2021 = waterArea2021.getInfo();
  const count1984 = pixelCount1984.getInfo();

  console.log(`Valid pixels in 1984: ${count1984}`);
  console.log(`Water pixels in 1984: ${area1984}`);
  console.log(`Water pixels in 2021: ${area2021}`);

  // 7. Validation
  if (count1984 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (area1984 === null || area2021 === null || isNaN(area1984) || isNaN(area2021)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // 8. Determine answer
  // Shoreline retreat inland means water decreased (land expanded seaward)
  const waterDecrease = area1984 - area2021;
  const percentChange = ((waterDecrease / area1984) * 100).toFixed(2);

  console.log(`Water change: ${waterDecrease.toFixed(0)} pixels (${percentChange}%)`);

  if (waterDecrease > area1984 * 0.05) {
    // Water decreased by more than 5% - shoreline retreated inland
    console.log('Shoreline retreated inland (water area decreased).');
    console.log('<answer>A</answer>');
  } else {
    console.log('No significant shoreline retreat (water stable or increased).');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
